function renderNationalCoverage(){
 const query=($('#nationalCoverageSearch')?.value||'').trim().toLowerCase();
 const rows=nationalCoverageRows.filter(x=>x.region.toLowerCase().includes(query));
 const active=nationalCoverageRows.filter(x=>x.is_active&&x.service_status==='available').length;
 const quote=nationalCoverageRows.filter(x=>x.is_active&&x.service_status==='quote_required').length;
 const paused=nationalCoverageRows.filter(x=>x.is_active&&x.service_status==='temporarily_unavailable').length;
 $('#nationalCoverageSummary').innerHTML='<div class="admin-row"><b>'+nationalCoverageRows.length+'</b><br><span class="muted">States & FCT listed</span></div><div class="admin-row"><b>'+active+'</b><br><span class="muted">Confirmed delivery areas</span></div><div class="admin-row"><b>'+quote+'</b><br><span class="muted">Quote required</span></div><div class="admin-row"><b>'+paused+'</b><br><span class="muted">Temporarily unavailable</span></div>';
 $('#nationalCoverageList').innerHTML=rows.map(x=>'<article class="feature"><div class="emoji">📍</div><h3>'+esc(x.region)+'</h3><p><span class="availability-status">'+esc(x.is_active?(x.service_status==='available'?'Delivery available':x.service_status==='temporarily_unavailable'?'Temporarily unavailable':'Quote required · contact Iyanda'):'Not active yet · expansion area')+'</span></p><p class="muted">'+(x.is_active&&x.service_status==='available'?(x.delivery_fee===null?'Delivery fee confirmed at checkout':'Delivery fee: '+esc(x.currency)+' '+esc(x.delivery_fee)):'Please contact Iyanda to confirm service for this location')+'</p></article>').join('')||'<p class="muted">No state matches that search.</p>';
}
