 const completed=rows.filter(o=>['delivered','collected'].includes(String(o.delivery_status||'').toLowerCase())||['delivered','collected'].includes(String(o.status||'').toLowerCase())).length;
 const cancelled=rows.filter(o=>['cancelled','refunded'].includes(String(o.status||'').toLowerCase())).length;
 const active=Math.max(0,rows.length-completed-cancelled);
 const points=rewardError?null:(rewards||[]).reduce((sum,item)=>sum+(Number(item.points)||0),0);
 const stats=[['Total orders',rows.length],['In progress',active],['Completed',completed],['Iyanda Rewards',points===null?'Unavailable':points.toLocaleString('en-NG')+' pts']];
