async function init(){ $('#year').textContent=new Date().getFullYear();saveCart();await loadProducts();await loadNationalCoverage();const {data}=await supabase.auth.getSession();await syncUser(data.session?.user??null,data.session);const params=new URLSearchParams(location.search),paymentReference=params.get('reference')||params.get('trxref');if(paymentReference){if(!data.session?.access_token){toast('Sign in again to confirm your payment status. Your payment reference has been kept so you can retry verification.');return}try{const verified=await fetch(SUPABASE_URL+'/functions/v1/iyanda-payment',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,Authorization:'Bearer '+data.session.access_token},body:JSON.stringify({action:'verify',reference:paymentReference})});const status=await verified.json();if(!verified.ok)throw new Error(status.error||'Payment verification failed');if(status.success){history.replaceState({},'',location.pathname+location.hash);toast('Paystack payment confirmed. Your Iyanda order is paid.');alert('Payment successful. Paystack has verified your transaction and your order is now marked as paid.');await loadCustomerOrders()}else{toast('Payment is not yet confirmed. Please check your order status.');alert('Paystack has not confirmed this payment yet. Do not pay again until you check your order status or contact Iyanda. Your payment reference remains available for another verification attempt.')}}catch(err){toast(err.message||'Could not verify payment. Your reference has been kept so you can retry.')}}}
