async function loadPromoAdmin(){
 if(!isAdmin())return;const box=$('#promoAdminList');if(!box)return;
 const {data,error}=await supabase.from('promo_codes').select('id,code,discount_type,discount_value,max_discount,min_subtotal,usage_limit,ends_at,is_active').order('created_at',{ascending:false}).limit(100);
 if(error){box.textContent='Promo codes unavailable: '+error.message;return}
 box.innerHTML=(data||[]).map(p=>'<div class="admin-row"><b>'+esc(p.code)+'</b> · '+esc(p.discount_type==='percentage'?p.discount_value+'%':money(p.discount_value))+' · '+(p.is_active?'Active':'Inactive')+'<p class="muted">Minimum '+money(p.min_subtotal)+' · Uses '+(p.usage_limit??'unlimited')+' · Expires '+(p.ends_at?new Date(p.ends_at).toLocaleDateString('en-NG'):'never')+'</p>'+(p.is_active?'<button class="btn small light" type="button" data-promo-deactivate="'+p.id+'">Deactivate</button>':'')+'</div>').join('')||'<p class="muted">No promotional codes created.</p>';
}
async function validateCheckoutPromo(){
 const field=$('#checkoutPromoCode'),feedback=$('#promoCodeFeedback');if(!field||!feedback)return;
 const code=field.value.trim().toUpperCase();if(!code){feedback.textContent='Enter a promo code first.';return}
 if(!user){feedback.textContent='Sign in to validate a promotion.';return}
 const rows=Object.entries(cart).map(([id,quantity])=>({p:products.find(x=>x.id===id),quantity})).filter(x=>x.p);
 if(!rows.length||rows.some(x=>x.p.price==null)){feedback.textContent='Promotions apply to priced products only.';return}
 const currencies=[...new Set(rows.map(x=>String(x.p.currency||'NGN').toUpperCase()))];if(currencies.length!==1){feedback.textContent='Use one currency per order.';return}
 const subtotal=rows.reduce((n,x)=>n+Number(x.p.price||0)*x.quantity,0);
 feedback.textContent='Checking promotion…';
 const {data,error}=await supabase.rpc('validate_marketplace_promo',{p_code:code,p_subtotal:subtotal,p_currency:currencies[0]});
 if(error){feedback.textContent='Promotion could not be checked. Please try again.';return}
 if(!data?.valid){feedback.textContent=data?.message||'This code cannot be applied.';return}
 field.value=data.code;feedback.textContent='✓ '+data.message+' · Discount '+money(data.discount_amount,currencies[0])+' (confirmed again when the order is placed).';
}
