function addBubble(text,who){const d=document.createElement('div');d.className='bubble '+(who==='me'?'me':'bot');const content=document.createElement('span');content.textContent=text;d.appendChild(content);if(who!=='me'){const listen=document.createElement('button');listen.type='button';listen.className='btn light small';listen.textContent='🔊 Listen';listen.style.marginTop='8px';listen.addEventListener('click',()=>speakIyanda(text));d.appendChild(listen)}$('#chatLog').appendChild(d);$('#chatLog').scrollTop=$('#chatLog').scrollHeight}
