function setupDashboardAccordions(){
 document.querySelectorAll('.contact-panel').forEach(panel=>{
  if(panel.dataset.iyandaAccordion==='ready')return;
  if(!panel.querySelector('.admin-list, .admin-grid, form'))return;
  const heading=panel.querySelector(':scope > h3, :scope > h4');
  if(!heading)return;
  panel.dataset.iyandaAccordion='ready';
  const details=document.createElement('details');
  details.className=panel.className;
  details.style.cssText=panel.style.cssText;
  details.dataset.iyandaAccordion='ready';
  const summary=document.createElement('summary');
  summary.style.cssText='cursor:pointer;display:flex;align-items:center;gap:8px;list-style-position:inside;font-weight:700;min-height:42px;';
  const eyebrow=heading.previousElementSibling?.classList.contains('eyebrow')?heading.previousElementSibling:null;
  if(eyebrow){summary.appendChild(eyebrow);eyebrow.style.margin='0 4px 0 0';}
  const title=document.createElement('span');
  title.textContent=heading.textContent.trim();
  summary.appendChild(title);
  const content=document.createElement('div');
  content.className='dashboard-accordion-content';
  let node=heading.nextSibling;
  while(node){const next=node.nextSibling;content.appendChild(node);node=next;}
  heading.remove();
  details.append(summary,content);
  panel.replaceWith(details);
 });
}
function setupLongListAccordions(){
 const selectors='.feature-grid, .products, .menu-department-links, .home-discovery-grid, .admin-list, .creative-library';
 const scan=()=>{
  document.querySelectorAll(selectors).forEach(container=>{
   const existing=container.querySelector(':scope > details[data-iyanda-more]');
   if(existing){
    const preceding=[...container.children].filter(el=>el!==existing);
    if(container.lastElementChild===existing&&preceding.length===Number(existing.dataset.itemCount))return;
    const extra=existing.querySelector('.iyanda-more-content');
    if(extra){while(extra.firstChild)container.insertBefore(extra.firstChild,existing)}
    existing.remove();
   }
   const items=[...container.children];
   if(items.length<=3)return;
   const hiddenItems=items.slice(3);
   const details=document.createElement('details');
   details.className='iyanda-more-items';
   details.dataset.iyandaMore='true';
   details.dataset.itemCount=String(items.length);
   const summary=document.createElement('summary');
   summary.textContent='Show '+hiddenItems.length+' more '+(hiddenItems.length===1?'item':'items');
   const content=document.createElement('div');
   content.className='iyanda-more-content';
   hiddenItems.forEach(item=>content.appendChild(item));
   details.append(summary,content);
   container.appendChild(details);
  });
 };
 scan();
 if(!document.documentElement.dataset.iyandaLongListObserver){
  document.documentElement.dataset.iyandaLongListObserver='ready';
  new MutationObserver(()=>scan()).observe(document.body,{childList:true,subtree:true});
 }
}
setupLongListAccordions();
