async function submitDeliveryQuote(orderId,action,fee){
 const {data:{session}}=await supabase.auth.getSession();if(!session?.access_token){toast('Please sign in again.');return}
 const response=await fetch(SUPABASE_URL+'/functions/v1/confirm-delivery-quote',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,Authorization:'Bearer '+session.access_token},body:JSON.stringify({order_id:orderId,action,delivery_fee:fee})});
 const result=await response.json();if(!response.ok)throw new Error(result.error||'Delivery quote update failed');
 toast(action==='unavailable'?'Order marked as unavailable for delivery.':'Delivery fee confirmed. Customer can now pay the updated total.');
 await loadDeliveryQuoteAdmin();await loadDispatchAdmin();await renderAdmin();
}
