const languageRunButton=$('#languageRun');if(languageRunButton){$('#languageAction').addEventListener('change',()=>{const action=$('#languageAction').value;$('#languageSource').disabled=action==='detect'||action==='lesson';$('#languageLevel').disabled=action!=='lesson';$('#languageTarget').disabled=action==='detect';$('#languageRun').textContent=action==='translate'?'Translate':action==='detect'?'Detect language':action==='explain'?'Explain phrase':'Create lesson'});$('#languageRun').addEventListener('click',async()=>{const text=$('#languageInput').value.trim();if(!text){toast('Enter text or a lesson topic first.');return}if(!user||!session){toast('Please sign in to use the Language Centre.');openAuth();return}const button=$('#languageRun');button.disabled=true;button.textContent='Working…';$('#languageStatus').textContent='Iyanda AI is processing your request…';$('#languageResult').textContent='Please wait…';try{const {data,error}=await supabase.functions.invoke('iyanda-language',{body:{action:$('#languageAction').value,text,source_language:$('#languageSource').value,target_language:$('#languageTarget').value,level:$('#languageLevel').value}});if(error){let detail=error.message||'The language request failed.';try{const body=await error.context.json();if(body?.error)detail=body.error}catch{}throw new Error(detail)}if(!data?.success||!data?.result)throw new Error(data?.error||'No result was returned.');$('#languageResult').textContent=data.result;$('#languageStatus').textContent='Completed · '+data.action+' · '+(data.model||'Iyanda AI')}catch(error){$('#languageResult').textContent=error?.message||'The language service is temporarily unavailable.';$('#languageStatus').textContent='Request not completed. Please try again.'}finally{button.disabled=false;const action=$('#languageAction').value;button.textContent=action==='translate'?'Translate':action==='detect'?'Detect language':action==='explain'?'Explain phrase':'Create lesson'}});$('#languageSaveWork').addEventListener('click',async()=>{const value=$('#languageResult').textContent.trim();if(!value||value.startsWith('Your translation')||value==='Please wait…'){toast('There is no completed language result to save.');return}await savedWorkSave('Language Centre: '+$('#languageAction').value,value,$('#languageAction').value==='lesson'?'lesson':'language',{source:'language-centre',action:$('#languageAction').value,source_language:$('#languageSource').value,target_language:$('#languageTarget').value})});$('#languageClear').addEventListener('click',()=>{$('#languageInput').value='';$('#languageResult').textContent='Your result will appear here.';$('#languageStatus').textContent=user?'Ready for your next language request.':'Sign in to use the private Language Centre.'});$('#languageCopy').addEventListener('click',async()=>{const value=$('#languageResult').textContent.trim();if(!value||value.startsWith('Your translation')){toast('There is no result to copy yet.');return}try{await navigator.clipboard.writeText(value);toast('Result copied.')}catch{toast('Copy is not available in this browser.')}})}




/* Iyanda One multi-page router with 1.5-second windmill transition */
(()=>{
 const main=document.querySelector('main');
 const pageIds=['home','shop','ai','features','games','farmCentre','customerHub','deliveryInfo','orderTracking','loyalty','afterSales','faq','farmGames','farmQuiz','farmAdventure','harvestChallenge','contact','dailyLifeSection','workspaceSection','creativeStudioSection','languageCentre','admin'];
 const pageNames={home:'Home',shop:'Shop & Products',ai:'Iyanda AI',features:'Services',games:'Games',farmCentre:'Farm Centre',customerHub:'Customer & Seller Hub',deliveryInfo:'Delivery and Collection',orderTracking:'Order Updates',loyalty:'Customer Loyalty',afterSales:'After-sales Support',faq:'Frequently Asked Questions',farmGames:'Farm Games',farmQuiz:'Farm Knowledge Quiz',farmAdventure:'Farm Adventure',harvestChallenge:'Harvest Challenge',contact:'Contact & Support',dailyLifeSection:'Daily Life',workspaceSection:'My Workspace',creativeStudioSection:'Creative Studio',languageCentre:'Language Centre',admin:'Iyanda Admin'};
 const aliases={daily:'dailyLifeSection','daily-life':'dailyLifeSection',workspace:'workspaceSection',creative:'creativeStudioSection','creative-studio':'creativeStudioSection',languages:'languageCentre',language:'languageCentre',services:'features',products:'shop',market:'shop',assistant:'ai',farm:'farmCentre','farm-centre':'farmCentre',seller:'customerHub',sellers:'customerHub','customer-hub':'customerHub','iyanda-admin':'admin','admin-dashboard':'admin',delivery:'deliveryInfo','delivery-info':'deliveryInfo','track-order':'orderTracking',orders:'orderTracking','customer-loyalty':'loyalty','after-sales':'afterSales',faqs:'faq','customer-help':'customerHub',customerAssistant:'customerHub','farm-games':'farmGames','farm-quiz':'farmQuiz','farm-adventure':'farmAdventure','harvest-challenge':'harvestChallenge'};
 const byAlias=id=>pageIds.includes(id)?id:(aliases[id]||'home');
 const current=()=>byAlias((location.hash||'#/home').replace(/^#\/?/,'').split(/[?&]/)[0]);
 const loader=document.getElementById('iyandaPageLoader');
 let transitionTimer=null,transitionToken=0,currentPage=null;
 const showPage=page=>{
  pageIds.forEach(id=>{const el=document.getElementById(id);if(!el)return;const active=id===page;el.classList.toggle('iyanda-active-page',active);el.setAttribute('aria-hidden',active?'false':'true')});
  currentPage=page;
  document.title=(pageNames[page]||'Iyanda One')+' | Iyanda One — A connected global platform';
  const results=document.getElementById('globalSearchResults');if(results)results.classList.remove('show');
  const menu=document.getElementById('mainMenuOverlay');if(menu){menu.classList.remove('show');menu.setAttribute('aria-hidden','true');document.body.style.overflow=''}
  window.scrollTo({top:0,behavior:'instant'});
 };
 const render=(forced,animate=false)=>{
  const page=forced||current();
  if(page==='admin'&&!isAdmin()){location.hash='#/home';return}
  if(page===currentPage&&!animate)return;
  main.classList.add('iyanda-page-mode');
  if(!animate||!currentPage){if(loader)loader.classList.remove('is-visible');showPage(page);return}
  const token=++transitionToken;
  if(transitionTimer)clearTimeout(transitionTimer);
  pageIds.forEach(id=>{const el=document.getElementById(id);if(el){el.classList.remove('iyanda-active-page');el.setAttribute('aria-hidden','true')}});
  const title=loader?.querySelector('.iyanda-loader-title');
  if(title)title.textContent='Opening '+(pageNames[page]||'Iyanda')+'…';
  loader?.classList.add('is-visible');loader?.setAttribute('aria-hidden','false');
  transitionTimer=setTimeout(()=>{
   if(token!==transitionToken)return;
   showPage(page);
   loader?.classList.remove('is-visible');loader?.setAttribute('aria-hidden','true');
   transitionTimer=null;
  },1500);
 };
 const navigate=id=>{
  const page=byAlias(id);
  const hash='#/'+(page==='dailyLifeSection'?'daily-life':page==='workspaceSection'?'workspace':page==='creativeStudioSection'?'creative-studio':page==='languageCentre'?'languages':page);
  if(location.hash!==hash)location.hash=hash;else render(page,true);
 };
 window.iyandaNavigate=navigate;
 document.addEventListener('click',e=>{
  const a=e.target.closest('a[href]');if(!a)return;
  let u;try{u=new URL(a.href,location.href)}catch{return}
  if(u.origin!==location.origin||!u.hash)return;
  const raw=u.hash.replace(/^#\/?/,'').split(/[?&]/)[0];if(!raw)return;
  const page=byAlias(raw);if(!pageIds.includes(page))return;
  e.preventDefault();navigate(page);
 });
 window.addEventListener('hashchange',()=>render(undefined,true));
 render();
})();

