  productMatches.forEach(p=>{const b=document.createElement('button');b.type='button';b.className='global-search-result';const icon=document.createElement('span');icon.className='result-icon';icon.textContent='📦';const wrap=document.createElement('span');const strong=document.createElement('b');strong.textContent=p.name;const small=document.createElement('small');small.textContent='Product · '+(p.category||'Iyanda Market');wrap.append(strong,small);b.append(icon,wrap);b.addEventListener('click',()=>{results.classList.remove('show');document.getElementById('productSearch').value=p.name;renderProducts();document.getElementById('shop').scrollIntoView({behavior:'smooth'})});results.appendChild(b)});
